<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
type Row=Record<string,any>
const props=defineProps<{api:(path:string,method?:string,body?:any)=>Promise<any>}>()
const users=ref<Row[]>([]),groups=ref<Row[]>([]),services=ref<Row[]>([]),profiles=ref<Row[]>([]),error=ref(''),notice=ref(''),busy=ref(false),tab=ref('users')
const user=ref({id:'',name:'',enabled:true,expires_at:new Date(Date.now()+30*86400000).toISOString().slice(0,10),rotate_credentials:false})
const group=ref({id:'',name:'',user_ids:[] as string[],service_ids:[] as string[],version:0})
const profile=ref({id:'',name:'',format:'sing-box',local_port:1080,selection:'select',test_url:'https://www.gstatic.com/generate_204'})
const subscription=ref({name:'',user_id:'',profile_id:'',days:30}),share=ref(''),format=ref('sing-box')
let alive=true;onUnmounted(()=>{alive=false;share.value=''})
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){if(alive)error.value=String(e)}finally{if(alive)busy.value=false}}
async function reload(){const d=await Promise.all(['proxy-users','user-groups','live','client-profiles'].map(p=>props.api(p)));if(alive)[users.value,groups.value,services.value,profiles.value]=d}
onMounted(()=>void run(reload))
function saveUser(){void run(async()=>{const {id,...body}=user.value;await props.api('proxy-users'+(id?'/'+id:''),id?'PUT':'POST',{...body,expires_at:new Date(body.expires_at+'T23:59:59Z').toISOString()});notice.value='用户已保存。凭据由控制端生成，停用或到期将在 Agent 下一次同步撤销服务端授权。';user.value.id='';user.value.name='';user.value.rotate_credentials=false;await reload()})}
function editUser(row:Row){user.value={id:row.id,name:row.name,enabled:row.enabled,expires_at:row.expires_at.slice(0,10),rotate_credentials:false}}
function saveGroup(){void run(async()=>{const {id,...body}=group.value;await props.api('user-groups'+(id?'/'+id:''),id?'PUT':'POST',body);notice.value='组权限已更新；完整主机内核配置将统一重新部署。';group.value={id:'',name:'',user_ids:[],service_ids:[],version:0};await reload()})}
function editGroup(row:Row){group.value={id:row.id,name:row.name,user_ids:[...row.user_ids],service_ids:[...row.service_ids],version:row.version}}
function saveProfile(){void run(async()=>{const {id,...body}=profile.value;await props.api('client-profiles'+(id?'/'+id:''),id?'PUT':'POST',body);notice.value='客户端出站模板已保存。';profile.value.id='';profile.value.name='';await reload()})}
function editProfile(p:Row){profile.value={id:p.id,name:p.name,format:p.format,local_port:p.local_port,selection:p.selection,test_url:p.test_url}}
function createSubscription(){void run(async()=>{const result=await props.api('subscriptions','POST',subscription.value);share.value=result.url;const p=profiles.value.find(p=>p.id===subscription.value.profile_id);format.value=p?.format||'sing-box';notice.value='专属链接只显示一次，请保存。用户组变动会自动反映在订阅内。'})}
async function copy(){try{await navigator.clipboard.writeText(share.value+'?format='+format.value);notice.value='订阅链接已复制'}catch{error.value='请手动选择并复制链接'}}
</script>
<template>
<section class="users-workspace"><nav class="topology-tabs"><button v-for="t in [{id:'users',name:'用户'},{id:'groups',name:'用户组与入站权限'},{id:'profiles',name:'客户端出站模板'},{id:'subscriptions',name:'用户订阅'}]" :key="t.id" class="secondary" :class="{active:tab===t.id}" @click="tab=t.id">{{t.name}}</button></nav>
<p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>
<section v-if="tab==='users'" class="panel publish-card"><span class="eyebrow">IDENTITY / ACCESS</span><h2>独立身份，按组授权</h2><p class="muted">每个用户具有独立 UUID 和密码。先创建用户，在逻辑节点中开启“按用户 / 用户组授权”，再分配组权限。停用会撤销服务端身份；撤销分享链接仅停止订阅下载。</p><form @submit.prevent="saveUser"><div class="fields"><label>用户名称<input v-model="user.name" required maxlength="100"></label><label>有效期至<input v-model="user.expires_at" type="date" required></label><label class="check-label"><input v-model="user.enabled" type="checkbox">允许使用</label><label v-if="user.id" class="check-label"><input v-model="user.rotate_credentials" type="checkbox">轮换用户凭据</label></div><button class="primary" :disabled="busy">{{user.id?'更新用户':'创建用户'}}</button><button v-if="user.id" class="secondary" type="button" @click="user.id='';user.name=''">取消编辑</button></form><div class="table-scroll"><table><thead><tr><th>用户</th><th>状态</th><th>有效期</th><th>操作</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.name}}</td><td><span :class="['status',u.active?'succeeded':'pending']">{{u.active?'有效':u.enabled?'已到期':'已停用'}}</span></td><td>{{new Date(u.expires_at).toLocaleString()}}</td><td><button class="text-button" @click="editUser(u)">编辑 / 停用</button></td></tr></tbody></table></div></section>
<section v-if="tab==='groups'" class="panel publish-card"><span class="eyebrow">GROUP → INBOUNDS</span><h2>用户组与入站权限</h2><form @submit.prevent="saveGroup"><label>用户组名称<input v-model="group.name" required maxlength="100"></label><div class="permission-grid"><fieldset><legend>组内用户</legend><label v-for="u in users" :key="u.id" class="check-label"><input v-model="group.user_ids" :value="u.id" type="checkbox">{{u.name}} {{u.active?'':'（已停用 / 到期）'}}</label></fieldset><fieldset><legend>允许使用的入站</legend><label v-for="s in services.filter(s=>s.managed_users)" :key="s.id" class="check-label"><input v-model="group.service_ids" :value="s.id" type="checkbox">{{s.name}} · {{s.engine}} / {{s.kind}}</label><p class="muted">入站需先开启按用户授权。SS 2022 / Snell 当前采用独立共享密钥入站，不参与用户组授权。</p></fieldset></div><button class="primary" :disabled="busy">{{group.id?'更新组权限':'创建用户组'}}</button></form><div v-for="g in groups" :key="g.id" class="group-item"><div><b>{{g.name}}</b><small class="block-muted">{{g.user_ids.length}} 位用户 · {{g.service_ids.length}} 个入站</small></div><button class="text-button" @click="editGroup(g)">修改成员与权限</button></div></section>
<section v-if="tab==='profiles'" class="panel publish-card"><span class="eyebrow">CLIENT OUTBOUND PROFILES</span><h2>客户端配置模板</h2><p class="muted">模板控制客户端本地入口和节点选择方式；协议出站由服务端入站对应生成。不会将服务器私钥或整个服务端配置发给客户端。</p><form @submit.prevent="saveProfile"><div class="fields"><label>模板名称<input v-model="profile.name" required maxlength="100"></label><label>客户端格式<select v-model="profile.format"><option value="xray">Xray JSON</option><option value="sing-box">sing-box JSON</option><option value="mihomo">Mihomo JSON / YAML 兼容</option><option value="shadowrocket">Shadowrocket URI 订阅</option></select></label><label>客户端本地端口<input v-model.number="profile.local_port" type="number" min="1024" max="65535" required></label><label>节点选择策略<select v-model="profile.selection"><option value="select">手动选择</option><option value="urltest">自动延迟选择</option></select></label><label>连通性探测网址<select v-model="profile.test_url"><option>https://www.gstatic.com/generate_204</option><option>https://cp.cloudflare.com/generate_204</option></select></label></div><p v-if="profile.format==='shadowrocket'" class="muted">URI 订阅仅包含连接入口，本地端口和分组策略由 Shadowrocket 自身控制。AnyTLS / Snell 请选择 JSON 客户端。</p><button class="primary" :disabled="busy">保存模板</button></form><div v-for="p in profiles" :key="p.id" class="group-item"><div><b>{{p.name}}</b><small class="block-muted">{{p.format}} · {{p.selection}} · 127.0.0.1:{{p.local_port}}</small></div><button class="text-button" @click="editProfile(p)">编辑模板</button></div></section>
<section v-if="tab==='subscriptions'" class="panel publish-card"><h2>生成用户专属订阅</h2><p class="muted">将自动包含此用户所属组授权的全部入站。已停用、到期、离线或配置尚未应用的入口不予发布。</p><form @submit.prevent="createSubscription"><div class="fields"><label>订阅名称<input v-model="subscription.name" required></label><label>所属用户<select v-model="subscription.user_id" required><option value="">选择用户</option><option v-for="u in users.filter(u=>u.active)" :key="u.id" :value="u.id">{{u.name}}</option></select></label><label>配置模板<select v-model="subscription.profile_id"><option value="">默认手动选择模板</option><option v-for="p in profiles" :key="p.id" :value="p.id">{{p.name}} · {{p.format}}</option></select></label><label>链接有效天数<input v-model.number="subscription.days" type="number" min="1" max="365" required></label></div><button class="primary" :disabled="busy">生成专属订阅</button></form><div v-if="share" class="share-result"><label>手动选择格式<select v-model="format"><option value="xray">Xray JSON</option><option value="sing-box">sing-box</option><option value="mihomo">Mihomo</option><option value="shadowrocket">Shadowrocket</option></select></label><code>{{share}}?format={{format}}</code><button class="secondary" @click="copy">复制订阅链接</button></div></section>
</section>
</template>
<style scoped>
.topology-tabs{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:24px}.topology-tabs .active{color:var(--accent);border-color:var(--accent)}.permission-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:20px 0}fieldset{border:1px solid var(--border);border-radius:14px;padding:18px;max-height:360px;overflow:auto}fieldset label{margin:12px 0}.group-item{display:flex;justify-content:space-between;gap:20px;padding:20px 0;border-top:1px solid var(--border)}.share-result{display:grid;gap:14px;margin-top:24px}.share-result code{padding:16px;overflow-wrap:anywhere;background:var(--bg);border-radius:10px}@media(max-width:640px){.permission-grid{grid-template-columns:1fr}.topology-tabs button{flex:1;min-width:42%}}
</style>
